import{_ as t,o as a,c as n,ah as i}from"./chunks/framework.DDXs_i7t.js";const d=JSON.parse(`{"title":"March 18: The 'Examining Out' Scandal – Details from Linz","description":"Applicants in the Wöginger trial report deliberate disadvantage through absurd trick questions during the hearing.","frontmatter":{"title":"March 18: The 'Examining Out' Scandal – Details from Linz","description":"Applicants in the Wöginger trial report deliberate disadvantage through absurd trick questions during the hearing.","date":"2026-03-18T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-03-18-hinauspruefen-skandal.md","filePath":"en/logbuch/2026-03-18-hinauspruefen-skandal.md"}`),o={name:"en/logbuch/2026-03-18-hinauspruefen-skandal.md"};function r(s,e,h,l,c,g){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="⚖️-march-18-the-examining-out-scandal-–-details-from-linz" tabindex="-1">⚖️ March 18: The &quot;Examining Out&quot; Scandal – Details from Linz <a class="header-anchor" href="#⚖️-march-18-the-examining-out-scandal-–-details-from-linz" aria-label="Permalink to &quot;⚖️ March 18: The &quot;Examining Out&quot; Scandal – Details from Linz&quot;">​</a></h1><p>It is <strong>Wednesday, March 18, 2026 (23:05 PM)</strong>. While the judiciary evaluates yesterday&#39;s witness statements, the extent of the &quot;Wöginger system&quot; is becoming increasingly clear. Today, reports about so-called <strong>&quot;examining out&quot;</strong> (Hinausprüfen) dominate the headlines.</p><h3 id="targeted-sabotage-in-the-hearing" tabindex="-1"><strong>Targeted Sabotage in the Hearing?</strong> <a class="header-anchor" href="#targeted-sabotage-in-the-hearing" aria-label="Permalink to &quot;**Targeted Sabotage in the Hearing?**&quot;">​</a></h3><p>Several witnesses (competitors for the management of the Braunau tax office) consistently described a bizarre situation at the 2017 hearing:</p><ul><li><strong>Absurd Detailed Questions:</strong> While the favored ÖVP mayor was spared, the technically superior competitors were confronted with extremely specific questions (e.g., technical details about telephony) that had nothing to do with the actual management function.</li><li><strong>The Goal:</strong> To artificially depress the qualification assessment of the competitors in order to present the mayor as the &quot;best suited.&quot;</li><li><strong>The Call:</strong> One witness also confirmed that he had been called in advance from the Ministry of Finance with the blunt request to withdraw his application.</li></ul><h3 id="woginger-s-silence-on-sabotage" tabindex="-1"><strong>Wöginger&#39;s Silence on Sabotage</strong> <a class="header-anchor" href="#woginger-s-silence-on-sabotage" aria-label="Permalink to &quot;**Wöginger&#39;s Silence on Sabotage**&quot;">​</a></h3><p>August Wöginger sticks to his defense line of &quot;citizen surgeries&quot; and continues to label the accusations by Thomas Schmid as &quot;fiction.&quot; The defense has so far remained largely silent on the specific sabotage allegations at the hearing.</p><h3 id="significance-for-the-horten-mystery" tabindex="-1"><strong>Significance for the &quot;Horten Mystery&quot;</strong> <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;**Significance for the &quot;Horten Mystery&quot;**&quot;">​</a></h3><p>These details are of invaluable value for <strong>Part 4: The Political Love Story</strong>:</p><ol><li><strong>Metaphor of Sabotage:</strong> &quot;Examining out&quot; will become a central motif for dealing with critics in our mockumentary.</li><li><strong>The Architecture of Patronage:</strong> We see here the &quot;workshop&quot; where positions are custom-made and competitors are dismantled.</li><li><strong>Aura of Injustice:</strong> The witnesses&#39; descriptions give our project an additional level of documentary weight.</li></ol><hr><p><strong>&quot;In a system of favorites, excellence is a danger that must be &#39;examined out&#39;.&quot;</strong></p><p>👉 <a href="/en/">Follow the Live Ticker on the homepage</a> 👉 <a href="/en/statistik.html">To the current Virality Index</a></p><hr><p><em>Reporting from March 18, 2026. Transparency is our only weapon.</em></p>',15)])])}const m=t(o,[["render",r]]);export{d as __pageData,m as default};
